// Hand-written `aws-sdk` (version 2) stub for the flowatlas fixture suite.
//
// Version 2 is one package for every service: a namespace object holding one
// class per service, each method taking its input directly and answering with
// a request whose `promise()` is awaited. Only the queue client is here,
// because that is the only version 2 call the fixture makes.

export declare class Request<T> {
  promise(): Promise<T>;
}

export declare namespace SQS {
  interface SendMessageRequest {
    QueueUrl: string;
    MessageBody: string;
    DelaySeconds?: number;
  }
  interface SendMessageResult {
    MessageId?: string;
  }
}

export declare class SQS {
  constructor(options?: { region?: string; apiVersion?: string });
  sendMessage(params: SQS.SendMessageRequest): Request<SQS.SendMessageResult>;
}

declare const AWS: {
  SQS: typeof SQS;
};

export default AWS;
